  reg [2:0] next_state;

  always @(posedge clk) begin
    if (!resetn) begin
      state <= 3'b000;
    end else begin
      state <= next_state;
    end
  end

  always @(*) begin
    case (state)
      3'b000: begin
        if (r[0] == 1'b0 && r[1] == 1'b0 && r[2] == 1'b0) begin
