        end else if (r[0] == 1'b1) begin
          next_state = 3'b001;
        end else if (r[1] == 1'b1) begin
          next_state = 3'b010;
        end else if (r[2] == 1'b1) begin
          next_state = 3'b011;
        end
      end
      3'b001: begin
        if (r[0] == 1'b1) begin
          next_state = 3'b001;
        end else if (r[1] == 1'b1) begin
          next_state = 3'b010;
        end else if (r[2] == 1'b1) begin
          next_state = 3'b011;
