module pulp_clock_mux2
  (
   input  logic clk0_i,
   input  logic clk1_i,
   input  logic clk_sel_i,
   output logic clk_o
   );
always_comb
     begin
	if (clk_sel_i == 1'b0)
	  clk_o = clk0_i;
	else
	  clk_o = clk1_i;
     end
endmodule

module baud_gen (
    input clk, rst,
    input [7:0] div,
    output tick
);
reg [7:0] counter = 0;
    reg tick_reg = 0;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            tick_reg <= 0;
        end else begin
            if (counter == div - 1) begin
                counter <= 0;
                tick_reg <= 1;
            end else begin
                counter <= counter + 1;
                tick_reg <= 0;
            end
        end
    end

    assign tick = tick_reg;

endmodule

module addmulxor_1_stage_unsigned_9_bit_xor_reduction(
	input  [8:0] a,
	input  [8:0] b,
	input  [8:0] c,
	input  [8:0] d,
	output [8:0] out,
	input clk);
logic  [17:0] stage0;

	always @(posedge clk) begin
	stage0 <= ((d + a) * b) ^ c;

	end

	assign out = ^(stage0);
endmodule

module rtcl_p3s7_blinking_led
        #(
            parameter   int COUNT_LIMIT = 50_000_000
        )
        (
            input   var logic           clk50   ,
            input   var logic           clk72   ,
            output  var logic   [1:0]   led     ,
            output  var logic   [7:0]   pmod    
        );
logic   [31:0]   counter50;
    logic   [31:0]   counter72;

    always_ff @(posedge clk50) begin
        if (counter50 == COUNT_LIMIT) begin
            counter50 <= 0;
        end else begin
            counter50 <= counter50 + 1;
        end
    end

    always_ff @(posedge clk72) begin
        if (counter72 == COUNT_LIMIT) begin
            counter72 <= 0;
        end else begin
            counter72 <= counter72 + 1;
        end
    end

    assign led[1] = counter50[31];
    assign led[0] = counter72[31];

    assign pmod[7:0] = counter72[31:24];

endmodule

