module eb1_5 #(
	parameter WIDTH = 8,
	parameter S0 = 3'o0,
	parameter S1 = 3'o1,
	parameter S2 = 3'o2,
	parameter S3 = 3'o3,
	parameter S4 = 3'o4
) (
	input  clk, reset_n,
	input         [WIDTH-1:0] t0_data,
	input                     t0_valid,
	output logic              t0_ready,
	output logic  [WIDTH-1:0] i0_data,
	output logic              i0_valid,
	input                     i0_ready
);
logic [WIDTH-1:0] dat0, dat1;
logic [2:0] state, next_state;

always_ff @(posedge clk or negedge reset_n) begin
	if (!reset_n) begin
		state <= S0;
	end else begin
		state <= next_state;
	end
end

always_comb begin
	next_state = state;
	i0_data = dat0;
	i0_valid = 1'b0;
	t0_ready = 1'b0;
	case (state)
		S0: begin
			if (t0_valid & i0_ready) begin
				next_state = S1;
				i0_valid = 1'b1;
			end
		end
		S1: begin
			if (t0_valid & i0_ready) begin
				next_state = S2;
			end
		end
		S2: begin
			if (t0_valid & i0_ready) begin
				next_state = S3;
			end
		end
		S3: begin
			if (t0_valid & i0_ready) begin
				next_state = S4;
			end
		end
		S4: begin
			if (t0_valid & i0_ready) begin
				next_state = S1;
			end
		end
		default: next_state = S0;
	endcase
end

always_ff @(posedge clk or negedge reset_n) begin
	if (!reset_n) begin
		dat0 <= {WIDTH{1'b0}};
		dat1 <= {WIDTH{1'b0}};
	end else begin
		case (state)
			S0: dat0 <= t0_data;
			S1: dat0 <= t0_data;
			S2: dat1 <= t0_data;
			S3: dat1 <= t0_data;
			S4: dat0 <= t0_data;
			default: ;
		endcase
	end
end

endmodule

module fifo_simple
#(
    parameter               WIDTH=16,
    parameter               DEPTH=16,
    parameter               PROG_FULL=14
)    
(
    input   wire                    reset_p,    
    input   wire                    clk,        

    input   wire    [WIDTH-1:0]     data_i,
    input   wire                    data_we,

    output  wire    [WIDTH-1:0]     data_o,
    input   wire                    data_rd,

    output  wire                    prog_full,
    output  wire                    full,
    output  wire                    empty,
    output  reg                     overflow,
    output  reg                     underflow

);
reg [WIDTH-1:0] mem [DEPTH-1:0];
reg [WIDTH-1:0] word_count;
reg [WIDTH-1:0] wr_ptr;
reg [WIDTH-1:0] rd_ptr;

assign data_o = mem[rd_ptr];

assign full = (word_count == DEPTH);
assign empty = (word_count == 0);
assign prog_full = (word_count == PROG_FULL);

always @(posedge clk) begin
    if (reset_p) begin
        wr_ptr <= 0;
        rd_ptr <= 0;
        word_count <= 0;
        overflow <= 0;
        underflow <= 0;
    end else begin
        if (data_we && !full) begin
            mem[wr_ptr] <= data_i;
            wr_ptr <= wr_ptr + 1;
            word_count <= word_count + 1;
        end
        if (data_rd && !empty) begin
            rd_ptr <= rd_ptr + 1;
            word_count <= word_count - 1;
        end
        if (word_count == DEPTH) begin
            overflow <= 1;
        end
        if (word_count == 0) begin
            underflow <= 1;
        end
    end
end

endmodule

module submulor_2_stage_unsigned_10_bit(
	input  [9:0] a,
	input  [9:0] b,
	input  [9:0] c,
	input  [9:0] d,
	output [9:0] out,
	input clk);
logic  [19:0] stage0;
	logic  [19:0] stage1;

	always @(posedge clk) begin
	stage0 <= ((d - a) * b) | c;
	stage1 <= stage0;
	end

	assign out = stage1;
endmodule

