endmodule

module vga_ctrl(
input wire pixel_clk,
output wire hsync,
output wire vsync,
output wire [9:0] pixel_x,
output wire [9:0] pixel_y,
output wire visible_region
); 

parameter [31:0] h_total=640;
parameter [31:0] h_sync=16;
parameter [31:0] h_blank=48;
parameter [31:0] v_total=480;
parameter [31:0] v_sync=10;
parameter [31:0] v_blank=33;
reg [9:0] h_counter;
reg [9:0] v_counter;
reg [9:0] h_counter_next;
reg [9:0] v_counter_next;
reg h_sync_next;
reg h_blank_next;
reg v_sync_next;
reg v_blank_next;
reg [9:0] pixel_x_next;
reg [9:0] pixel_y_next;
reg visible_region_next;
  assign hsync = h_counter_next[h_sync];
  assign vsync = v_counter_next[v_sync];
  assign pixel_x = pixel_x_next;
  assign pixel_y = pixel_y_next;
  assign visible_region = visible_region_next;
  always @(posedge pixel_clk) begin
    h_counter <= h_counter_next;
    v_counter <= v_counter_next;
    h_sync <= h_sync_next;
    h_blank <= h_blank_next;
    v_sync <= v_sync_next;
    v_blank <= v_blank_next;
    pixel_x <= pixel_x_next;
    pixel_y <= pixel_y_next;
    visible_region <= visible_region_next;
  end
  always @(h_counter, v_counter, h_sync, h_blank, v_sync, v_blank) begin
    h_counter_next <= h_counter;
    v_counter_next <= v_counter;
    h_sync_next <= h_sync;
    h_blank_next <= h_blank;
    v_sync_next <= v_sync;
    v_blank_next <= v_blank;
    pixel_x_next <= pixel_x;
    pixel_y_next <= pixel_y;
    visible_region_next <= visible_region;
    if((h_counter == (h_total - 1))) begin
      h_counter_next <= 0;
      v_counter_next <= v_counter + 1;
    end
    else begin
      h_counter_next <= h_counter + 1;
      v_counter_next <= v_counter;
    end
    if((h_counter == (h_total - 1))) begin
      h_sync_next <= 1'b0;
    end
    else begin
      h_sync_next <= 1'b1;
    end
    if((h_counter == (h_total - 1))) begin
      h_blank_next <= 1'b0;
    end
    else begin
      h_blank_next <= 1'b1;
    end
    if((v_counter == (v_total - 1))) begin
      v_counter_next <= 0;
      h_counter_next <= 0;
    end
    else begin
      v_counter_next <= v_counter + 1;
      h_counter_next <= h_counter;
    end
    if((v_counter == (v_total - 1))) begin
      v_sync_next <= 1'b0;
    end
    else begin
      v_sync_next <= 1'b1;
    end
    if((v_counter == (v_total - 1))) begin
      v_blank_next <= 1'b0;
    end
    else begin
      v_blank_next <= 1'b1;
    end
    if((h_counter == (h_total - 1))) begin
      pixel_x_next <= 0;
    end
    else begin
      pixel_x_next <= pixel_x + 1;
    end
    if((v_counter == (v_total - 1))) begin
      pixel_y_next <= 0;
    end
    else begin
      pixel_y_next <= pixel_y + 1;
    end
    if((h_counter == (h_total - 1))) begin
      if((v_counter == (v_total - 1))) begin
        visible_region_next <= 1'b0;
      end
      else begin
        visible_region_next <= 1'b1;
      end
    end
    else begin
      visible_region_next <= 1'b1;
    end
  end
endmodule

