module spdr_uart_framer
(
    input clk_50,
    input rst,

    output reg tx_busy,
    input tx_vld,
    input [7:0] tx_data,

    output rx_vld,
    output [7:0] rx_data,
    output reg rx_frame_error,

    output uart_tx,
    input uart_rx
);
parameter sampling_clk_divider = 100000000;

reg [15:0] tx_counter;
reg [7:0] tx_shift_reg;
reg tx_busy_reg;

reg [15:0] rx_counter;
reg [7:0] rx_shift_reg;
reg rx_vld_reg;

always @(posedge clk_50) begin
    if (rst) begin
        tx_counter <= 0;
        tx_shift_reg <= 0;
        tx_busy_reg <= 0;
    end else begin
        if (tx_vld) begin
            tx_counter <= tx_counter + 1;
            if (tx_counter == 15'd100000000) begin
                tx_counter <= 0;
                tx_shift_reg <= {tx_shift_reg[6:0], tx_data[7]};
                tx_busy_reg <= 1;
            end
        end else begin
            tx_busy_reg <= 0;
        end
    end
end

always @(posedge clk_50) begin
    if (rst) begin
        rx_counter <= 0;
        rx_shift_reg <= 0;
        rx_vld_reg <= 0;
    end else begin
        if (rx_counter == 15'd100000000) begin
            rx_counter <= 0;
            rx_shift_reg <= {rx_shift_reg[6:0], uart_rx};
            rx_vld_reg <= 1;
        end else begin
            rx_counter <= rx_counter + 1;
            if (rx_counter == 15'd100000000) begin
                rx_counter <= 0;
                rx_vld_reg <= 0;
            end
        end
    end
end

always @(posedge clk_50) begin
    if (rst) begin
        rx_frame_error <= 0;
    end else begin
        if (rx_counter == 15'd100000000) begin
            rx_frame_error <= 0;
        end else if (rx_counter == 15'd100000000 - 1) begin
            if (rx_shift_reg[7:0] != 8'b11111111) begin
                rx_frame_error <= 1;
            end
        end
    end
end

assign uart_tx = tx_busy_reg;
assign rx_vld = rx_vld_reg;
assign rx_data = rx_shift_reg;

endmodule

