module toe_s_axis_listen_port_req_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam [1:0]
    ZERO = 2'b10,
    ONE  = 2'b11,
    TWO  = 2'b01;

reg  [N-1:0] data_p1;
reg  [N-1:0] data_p2;
wire         load_p1;
wire         load_p2;
reg          load_p1_from_p2;
reg  [1:0]   state;
reg  [1:0]   next;

assign s_ready = state[0];
assign m_data  = data_p1;
assign m_valid = state[1];

assign load_p1 = (state == ZERO && s_valid) ||
                 (state == ONE && s_valid && m_ready) ||
                 (state == TWO && m_ready);
assign load_p2 = s_valid & s_ready;
assign load_p1_from_p2 = (state == TWO);

always @(posedge clk) begin
    if (load_p1) begin
        if (load_p1_from_p2)
            data_p1 <= data_p2;
        else
            data_p1 <= s_data;
    end
end


always @(posedge clk) begin
    if (load_p2) data_p2 <= s_data;
end


always @(posedge clk) begin
    if (~reset)
        state <= ZERO;
    else
        state <= next;
end

always @(*) begin
    next = state;
    case (state)
        ZERO:
            if (s_valid & s_ready)
                next = ONE;
        ONE:
            if (~s_valid & m_ready)
                next = ZERO;
            else if (s_valid & ~m_ready)
                next = TWO;
        TWO:
            if (m_ready)
                next = ONE;
    endcase
end

endmodule

