module fifo36_demux
  #(parameter match_data = 0,
    parameter match_mask = 0)
   (input clk, input reset, input clear,
    input [35:0] data_i, input src_rdy_i, output dst_rdy_o,
    output [35:0] data0_o, output src0_rdy_o, input dst0_rdy_i,
    output [35:0] data1_o, output src1_rdy_o, input dst1_rdy_i);
localparam IDLE = 0, DATA0 = 1, DATA1 = 2;
   reg [1:0] state;
   reg [35:0] data0_o, data1_o;
   reg src0_rdy_o, src1_rdy_o;
   reg [35:0] src0_data, src1_data;
   reg eof;
   assign dst_rdy_o = dst0_rdy_i | dst1_rdy_i;
   assign src0_rdy_o = src0_data[35] & src_rdy_i;
   assign src1_rdy_o = src1_data[35] & src_rdy_i;
   assign data0_o = src0_data[35] ? src0_data : 0;
   assign data1_o = src1_data[35] ? src1_data : 0;
   always @(posedge clk) begin
      if (clear) begin
         state <= IDLE;
         src0_data <= 0;
         src1_data <= 0;
         src0_rdy_o <= 0;
         src1_rdy_o <= 0;
         eof <= 0;
      end
      else begin
         case (state)
            IDLE: begin
               if (src_rdy_i) begin
                  src0_rdy_o <= 1;
                  src1_rdy_o <= 0;
                  if (data_i[35:0] == match_data && data_i[35:0] == match_mask) begin
                     state <= DATA0;
                     src0_data <= data_i;
                     src1_data <= 0;
                  end
                  else begin
                     src0_data <= 0;
                     src1_data <= data_i;
                  end
               end
               else begin
                  src0_rdy_o <= 0;
                  src1_rdy_o <= 0;
               end
            end
            DATA0: begin
               if (dst0_rdy_i) begin
                  src0_rdy_o <= 0;
                  src1_rdy_o <= 1;
                  if (data_i[35:0] == match_data && data_i[35:0] == match_mask) begin
                     state <= DATA1;
                     src0_data <= 0;
                     src1_data <= data_i;
                  end
                  else begin
                     src0_data <= data_i;
                     src1_data <= 0;
                  end
               end
               else begin
                  src0_rdy_o <= 0;
                  src1_rdy_o <= 0;
               end
            end
            DATA1: begin
               if (dst1_rdy_i) begin
                  src0_rdy_o <= 1;
                  src1_rdy_o <= 0;
                  if (data_i[35:0] == match_data && data_i[35:0] == match_mask) begin
                     state <= IDLE;
                     src0_data <= 0;
                     src1_data <= data_i;
                  end
                  else begin
                     src0_data <= data_i;
                     src1_data <= 0;
                  end
               end
               else begin
                  src0_rdy_o <= 0;
                  src1_rdy_o <= 0;
               end
            end
            default: begin
               src0_rdy_o <= 0;
               src1_rdy_o <= 0;
            end
         endcase
      end
   end
endmodule

module branch_ctrl(
	input [31:0]	data_rs1	,
	input [31:0]	data_rs2	,
	input [2:0]		funct3		,
	output	reg		jmpb
);
always @(*) begin
		case (funct3)
			3'b000: jmpb = (data_rs1 == data_rs2);		#1;
			3'b001: jmpb = (data_rs1 != data_rs2);		#1;
			3'b010: jmpb = (data_rs1 < data_rs2);		#1;
			3'b011: jmpb = (data_rs1 > data_rs2);		#1;
			3'b100: jmpb = (data_rs1 < $signed(data_rs2));	#1;
			3'b101: jmpb = (data_rs1 > $signed(data_rs2));	#1;
			3'b110: jmpb = (data_rs1 < $unsigned(data_rs2));	#1;
			3'b111: jmpb = (data_rs1 > $unsigned(data_rs2));	#1;
		endcase
	end
endmodule

