module jtframe_romrq #(parameter AW=18, DW=8 )(
    input               rst,
    input               clk,
    input               clr, 
    input [21:0]        offset,
    input [AW-1:0]      addr,
    input               addr_ok,    
    input [31:0]        din,
    input               din_ok,
    input               we,
    output reg          req,
    output reg          data_ok,    
    output     [21:0]   sdram_addr,
    output reg [DW-1:0] dout
);
reg [AW-1:0] addr_req;
reg [DW-1:0] cached_data0, cached_data1;
reg [DW-1:0] cached_addr0, cached_addr1;
reg [DW-1:0] subaddr;
reg hit0, hit1, good;
reg [DW-1:0] addr_req0, addr_req1;

always @* begin
    addr_req = addr;
    if (DW == 8) begin
        addr_req = {addr_req[AW-2:0], 1'b0};
    end else if (DW == 16) begin
        addr_req = {addr_req[AW-4:0], 2'b00};
    end
    if (addr_req[AW-1:0] == cached_addr0[AW-1:0]) begin
        hit0 = 1;
    end else begin
        hit0 = 0;
    end
    if (addr_req[AW-1:0] == cached_addr1[AW-1:0]) begin
        hit1 = 1;
    end else begin
        hit1 = 0;
    end
    if (we && !hit0 && !hit1) begin
        cached_data0 <= din;
        cached_addr0 <= addr_req0;
        good <= 1;
    end else if (we && !hit0 && hit1) begin
        cached_data1 <= din;
        cached_addr1 <= addr_req1;
        good <= 1;
    end else if (we && hit0 && !hit1) begin
        cached_data0 <= din;
        cached_addr0 <= addr_req0;
        good <= 1;
    end else if (we && hit0 && hit1) begin
        if (addr_req0[DW-1:DW-2] == addr_req1[DW-1:DW-2]) begin
            cached_data0 <= din;
            cached_addr0 <= addr_req0;
            good <= 1;
        end else begin
            cached_data1 <= din;
            cached_addr1 <= addr_req1;
            good <= 1;
        end
    end else begin
        good <= 0;
    end
    if (addr_req[DW-1:DW-2] == 2'b00) begin
        subaddr = addr_req[DW-2:DW-3];
    end else begin
        subaddr = addr_req[DW-1:DW-3];
    end
    if (subaddr == 2'b00) begin
        req = hit0;
    end else if (subaddr == 2'b01) begin
        req = hit1;
    end else begin
        req = 0;
    end
    if (req) begin
        data_ok = 1;
    end else begin
        data_ok = 0;
    end
    if (we) begin
        sdram_addr = addr_req + offset;
    end else begin
        sdram_addr = addr_req0 + offset;
    end
    if (subaddr == 2'b00) begin
        dout = cached_data0;
    end else begin
        dout = cached_data1;
    end
end

endmodule

