  if (reset) begin
    state <= 4'b0000;
    data <= 8'b00000000;
  end else begin
    if (tick) begin
      case (state)
        4'b0000: begin
          if (io_valid) begin
            state <= 4'b0001;
            data <= io_bits;
          end
        end
        4'b0001: begin
          if (tick) begin
            state <= 4'b0010;
            data <= data >> 1;
          end
        end
        4'b0010: begin
          if (tick) begin
            state <= 4'b0011;
            data <= data >> 1;
          end
        end
        4'b0011: begin
          if (tick) begin
            state <= 4'b0100;
            data <= data >> 1;
          end
        end
        4'b0100: begin
          if (tick) begin
            state <= 4'b0101;
            data <= data >> 1;
          end
        end
