module CW_REGISTER(
input wire [2:0] D,
input wire [2:0] A,
input wire WR,
input wire RD,
input wire CLK,
input wire RST,
output wire WCTRL,
output reg [6:0] Y
); 

reg [6:0] data;
reg [6:0] next_data;
reg [2:0] next_ctrl;
  always @(posedge CLK, posedge RST) begin
    if(RST == 1'b1) begin
      data <= 7'b0000000;
      next_data <= 7'b0000000;
    end else begin
      data <= next_data;
      next_data <= D;
    end
  end
  always @(posedge CLK, posedge RST) begin
    if(RST == 1'b1) begin
      next_ctrl <= 3'b000;
    end else begin
      if(WR == 1'b1) begin
        next_ctrl <= A;
      end
      else if(RD == 1'b1) begin
        next_ctrl <= data;
      end
    end
  end
  always @(data, next_ctrl) begin
    case(next_ctrl)
    3'b000 : begin
      Y <= 7'b0000000;
    end
    3'b001 : begin
      Y <= 7'b0000001;
    end
    3'b010 : begin
      Y <= 7'b0000010;
    end
    3'b011 : begin
      Y <= 7'b0000100;
    end
    3'b100 : begin
      Y <= 7'b0001000;
    end
    3'b101 : begin
      Y <= 7'b0010000;
    end
    3'b110 : begin
      Y <= 7'b0100000;
    end
    3'b111 : begin
      Y <= 7'b1000000;
    end
    default : begin
      Y <= 7'b0000000;
    end
    endcase
  end
  assign WCTRL = next_ctrl[2];
endmodule

