module io_ps2_keyboard(
input wire clk,
input wire kbd_clk,
input wire kbd_dat,
output reg interrupt,
output reg [7:0] scanCode
); 

parameter CLK_SPEED = 100000000;
parameter timeout_const = 10000000;
parameter debounce_const = 1000000;
reg [7:0] shift_reg;
reg clk_filter;
reg [7:0] bitsCount;
reg [7:0] timeout;
reg [7:0] debounce;
  always @(posedge clk) begin
    if((timeout == 0)) begin
      timeout <= timeout_const;
      clk_filter <= 1'b0;
    end
    else begin
      timeout <= timeout - 1;
      clk_filter <= 1'b1;
    end
  end
  always @(posedge clk) begin
    if((timeout == 0)) begin
      debounce <= debounce_const;
    end
    else begin
      debounce <= debounce - 1;
    end
  end
  always @(posedge clk) begin
    if((debounce == 0)) begin
      debounce <= debounce_const;
      shift_reg <= {shift_reg[6:0],kbd_dat};
    end
    else begin
      debounce <= debounce - 1;
    end
  end
  always @(posedge clk) begin
    if((clk_filter == 1'b1)) begin
      if((bitsCount == 0)) begin
        bitsCount <= 1;
        interrupt <= 1'b0;
      end
      else begin
        bitsCount <= bitsCount + 1;
        if((bitsCount == 8)) begin
          interrupt <= 1'b1;
          scanCode <= shift_reg;
        end
      end
    end
    else begin
      bitsCount <= 0;
      interrupt <= 1'b0;
    end
  end
endmodule

