input wire RST,
input wire CLK,
output wire H_SYNC,
output wire V_SYNC,
output wire [10:0] X,
output wire [10:0] Y,
output wire DISP_EN
); 

parameter [10:0] H_ACTIVE=1280;
parameter [10:0] H_FRONT=16;
parameter [10:0] H_BACK=48;
parameter [10:0] H_SYNC=96;
parameter [10:0] H_TOTAL=1392;
parameter [10:0] V_ACTIVE=720;
parameter [10:0] V_FRONT=10;
parameter [10:0] V_BACK=2;
parameter [10:0] V_SYNC=2;
parameter [10:0] V_TOTAL=752;
reg [10:0] X;
reg [10:0] Y;
reg H_SYNC;
reg V_SYNC;
reg DISP_EN;
  always @(posedge CLK, posedge RST) begin
    if(RST == 1'b1) begin
      X <= 11'b00000000000;
      Y <= 11'b0000000000;
      H_SYNC <= 1'b0;
      V_SYNC <= 1'b0;
      DISP_EN <= 1'b0;
    end else begin
      if(X == H_TOTAL - 1) begin
        X <= 11'b00000000000;
        if(Y == V_TOTAL - 1) begin
          Y <= 11'b0000000000;
        end
        else begin
          Y <= Y + 1;
        end
      end
      else begin
        X <= X + 1;
      end
      if(X < H_ACTIVE) begin
        H_SYNC <= 1'b0;
      end
      else begin
        H_SYNC <= 1'b1;
      end
      if(Y < V_ACTIVE) begin
        V_SYNC <= 1'b0;
      end
      else begin
        V_SYNC <= 1'b1;
      end
      if(X < H_ACTIVE && Y < V_ACTIVE) begin
        DISP_EN <= 1'b1;
      end
      else begin
        DISP_EN <= 1'b0;
      end
    end
  end
  assign H_SYNC = H_SYNC;
  assign V_SYNC = V_SYNC;
  assign X = X;
  assign Y = Y;
