wire [1:0] prg_bank_out, chr_bank_out;
wire [21:0] prg_aout_out, chr_aout_out;
wire prg_allow_out, chr_allow_out, vram_a10_out, vram_ce_out;

assign prg_bank_out = prg_bank;
assign chr_bank_out = chr_bank;
assign prg_aout_out = prg_aout;
assign chr_aout_out = chr_aout;
assign prg_allow_out = prg_allow;
assign chr_allow_out = chr_allow;
assign vram_a10_out = vram_a10;
assign vram_ce_out = vram_ce;

always @(posedge clk) begin
    if (ce) begin
        if (reset) begin
            prg_bank <= 2'b00;
