module dhcp_client_m_axis_open_port_fifo
#(parameter
    DATA_BITS  = 8,
    DEPTH_BITS = 4
)(
    input  wire                 clk,
    input  wire                 aclr,
    output wire                 empty_n,
    output wire                 full_n,
    input  wire                 read,
    input  wire                 write,
    output wire [DATA_BITS-1:0] dout,
    input  wire [DATA_BITS-1:0] din
);
localparam
    DEPTH = 1 << DEPTH_BITS;

reg                 empty;
reg                 full;
reg  [DEPTH_BITS-1:0] index;

reg  [DATA_BITS-1:0] mem [0:DEPTH-1];

assign empty_n = ~empty;
assign full_n  = ~full;
assign dout    = mem[index];

always @(posedge clk) begin
    if (aclr)
        empty <= 1'b1;
    else if (empty & write)
        empty <= 1'b0;
    else if (full & read)
        full  <= 1'b1;
    else if (full & ~read)
        full  <= 1'b0;
end

always @(posedge clk) begin
    if (aclr)
        index <= {DEPTH_BITS{1'b1}};
    else if (write & ~empty)
        index <= index - 1;
    else if (read & ~full)
        index <= index + 1;
end

always @(posedge clk) begin
    if (aclr)
        mem[0] <= {DATA_BITS{1'b0}};
    else if (write & ~empty)
        mem[index] <= din;
end

endmodule

