module synchronize(
    input clk,
    input async_in,
    input reset,
    output reg sync_out
    );
reg sync_in;
    always @(posedge clk or posedge reset)
    begin
        if(reset)
            sync_in <= 0;
        else
            sync_in <= async_in;
    end
    always @(posedge clk or posedge reset)
    begin
        if(reset)
            sync_out <= 0;
        else
            sync_out <= sync_in;
    end
endmodule

module pipelined_multiplier (a, b, clk, pdt);
input [size-1 : 0] a;
input [size-1 : 0] b;
input clk;
output [2*size-1 : 0] pdt;
parameter size = 16;
parameter level = 2;

reg [2*size-1 : 0] pdt_int [level-1 : 0];
reg [size-1 : 0] a_int, b_int;

assign pdt = pdt_int[level-1];

always @(posedge clk) begin
    a_int <= a;
    b_int <= b;
    pdt_int[0] <= a_int * b_int;
    for (int i = 1; i < level; i++) begin
        pdt_int[i] <= pdt_int[i-1];
    end
end

endmodule

