module QueueCompatibility_14( 
  input        clock, 
  input        reset, 
  output       io_enq_ready, 
  input        io_enq_valid, 
  input  [3:0] io_enq_bits_tl_state_size, 
  input  [1:0] io_enq_bits_tl_state_source, 
  input        io_deq_ready, 
  output       io_deq_valid, 
  output [3:0] io_deq_bits_tl_state_size, 
  output [1:0] io_deq_bits_tl_state_source 
);
reg [3:0] state_size;
reg [1:0] state_source;
reg maybe_full;

assign io_enq_ready = io_enq_valid & io_deq_ready;
assign io_deq_valid = io_deq_ready & io_enq_valid;
assign io_deq_bits_tl_state_size = state_size;
assign io_deq_bits_tl_state_source = state_source;

always @(posedge clock) begin
  if (reset) begin
    state_size <= 4'h0;
    state_source <= 2'h0;
    maybe_full <= 1'b0;
  end else begin
    if (io_enq_valid & io_deq_valid) begin
      if (io_enq_bits_tl_state_size > io_deq_bits_tl_state_size) begin
        state_size <= io_enq_bits_tl_state_size;
        state_source <= io_enq_bits_tl_state_source;
      end
      maybe_full <= 1'b1;
    end else begin
      if (io_enq_valid) begin
        state_size <= io_enq_bits_tl_state_size;
        state_source <= io_enq_bits_tl_state_source;
      end
      maybe_full <= 1'b0;
    end
  end
end

endmodule

