module multpool_rdata_mux #(
  parameter NBITS     = 256,
  parameter NUM_RDATA = 1024) (
  input  wire               hclk,     
  input  wire               hresetn,  
  input  wire [3*NBITS-1:0] rdata [0 :NUM_RDATA-1],
  input  wire               valid_rd,
  output wire [3*NBITS-1:0] hrdata
);
localparam NUM_RDATA_PER_GROUP = NUM_RDATA / 4;
  localparam NUM_RDATA_PER_GROUP_HALF = NUM_RDATA_PER_GROUP / 2;
  reg [NBITS-1:0] rdata_group0, rdata_group1, rdata_group2, rdata_group3;
  always @(posedge hclk or negedge hresetn) begin
    if (!hresetn) begin
      rdata_group0 <= 0;
      rdata_group1 <= 0;
      rdata_group2 <= 0;
      rdata_group3 <= 0;
    end else begin
      if (valid_rd) begin
        rdata_group0 <= rdata[0 : NUM_RDATA_PER_GROUP_HALF-1];
        rdata_group1 <= rdata[NUM_RDATA_PER_GROUP_HALF : 2*NUM_RDATA_PER_GROUP_HALF-1];
        rdata_group2 <= rdata[2*NUM_RDATA_PER_GROUP_HALF : 3*NUM_RDATA_PER_GROUP_HALF-1];
        rdata_group3 <= rdata[3*NUM_RDATA_PER_GROUP_HALF : NUM_RDATA-1];
      end
    end
  end
  assign hrdata = rdata_group0 | rdata_group1 | rdata_group2 | rdata_group3;
endmodule

