  assign odd_bits = din[63:32];
  assign dout = even_bits | odd_bits;
endmodule

module mylfsr2(
input wire [7:0] starting,
output wire [7:0] lfsr2_out,
input wire clk,
input wire rst,
input wire en
); 

reg [7:0] lfsr2;
  assign lfsr2_out = lfsr2;
  always @(posedge clk, posedge rst) begin
    if((rst == 1'b0)) begin
      lfsr2 <= starting;
    end
    else if((en == 1'b1)) begin
      lfsr2 <= {lfsr2[6:0],lfsr2[7]};
    end
  end
endmodule

