module binary_updown_counter #(parameter BITS = 1)
        (input wire clk, input wire rst, input wire ena,
         input wire updown, output wire [BITS - 1:0] out, output wire ovf);
reg [BITS - 1:0] cnt;
    wire [BITS - 1:0] enable_wires;
    assign enable_wires[0] = ena;
    genvar i;
    generate for (i = 1; i < BITS; i = i + 1) begin: gen_loop
        assign enable_wires[i] = enable_wires[i - 1] & ena;
    end
    endgenerate
    always @(posedge clk, posedge rst) begin
        if (rst) begin
            cnt <= {BITS{1'b0}};
        end else begin
            if (enable_wires[BITS - 1]) begin
                if (updown) begin
                    cnt <= cnt + 1;
                end else begin
                    cnt <= cnt - 1;
                end
            end
        end
    end
    assign out = cnt;
    assign ovf = (cnt == 2 ** BITS - 1) ^ (cnt == 0);
endmodule

