module stratixiii_bias_logic (
    clk,
    shiftnld,
    captnupdt,
    mainclk,
    updateclk,
    capture,
    update
    );


input  clk;
input  shiftnld;
input  captnupdt;


output mainclk;
output updateclk;
output capture;
output update;
reg mainclk;
reg updateclk;
reg capture;
reg update;

initial begin
    mainclk = 0;
    updateclk = 0;
    capture = 0;
    update = 0;
end

always @(captnupdt or shiftnld or clk) begin
    case ({captnupdt, shiftnld})
        2'b10, 2'b11: begin
            updateclk = clk;
            capture = 1;
        end
        2'b01: begin
            updateclk = clk;
            capture = 0;
        end
        default: begin
            mainclk = clk;
            update = 1;
        end
    endcase
end

and (mainclk, mainclk, 1'b1);
and (updateclk, updateclk, 1'b1);
and (capture, capture, 1'b1);
and (update, update, 1'b1);

endmodule

module syn_gen
(
    input              I_pxl_clk   ,
    input              I_rst_n     ,
    input      [15:0]  I_h_total   ,
    input      [15:0]  I_h_sync    ,
    input      [15:0]  I_h_bporch  ,
    input      [15:0]  I_h_res     ,
    input      [15:0]  I_v_total   ,
    input      [15:0]  I_v_sync    ,
    input      [15:0]  I_v_bporch  ,
    input      [15:0]  I_v_res     ,
    input      [15:0]  I_rd_hres   ,
    input      [15:0]  I_rd_vres   ,
    input              I_hs_pol    ,
    input              I_vs_pol    ,
    output reg         O_rden      ,
    output reg         O_de        ,   
    output reg         O_hs        ,
    output reg         O_vs         
);
reg [15:0] V_cnt;
reg [15:0] H_cnt;

wire Pout_de_w;
wire Pout_hs_w;
wire Pout_vs_w;
wire Rden_w;

assign Pout_de_w = (H_cnt < I_rd_hres);
assign Pout_hs_w = (H_cnt < I_h_res);
assign Pout_vs_w = (V_cnt < I_rd_vres);
assign Rden_w = (V_cnt < I_v_res);

always @(posedge I_pxl_clk or negedge I_rst_n)
begin
    if (!I_rst_n)
    begin
        V_cnt <= 0;
        H_cnt <= 0;
    end
    else
    begin
        V_cnt <= V_cnt + 1;
        if (V_cnt == I_v_total)
        begin
            V_cnt <= 0;
            H_cnt <= H_cnt + 1;
        end
        else
            H_cnt <= H_cnt + 1;
    end
end

assign O_rden = Rden_w;
assign O_de = Pout_de_w;
assign O_hs = Pout_hs_w & I_hs_pol;
assign O_vs = Pout_vs_w & I_vs_pol;

endmodule

module alu
    #(parameter WIDTH = 32)
    (   input  [WIDTH - 1 : 0] a,b,
        input  [2 : 0] m,
        output reg [WIDTH - 1 : 0] y,
        output reg zf,      
        output reg cf,      
        output reg of      
    );
always @* begin
        case (m)
            3'b000: y = a + b; cf = y[WIDTH - 1]; of = a[WIDTH - 1] ^ b[WIDTH - 1] ^ y[WIDTH - 1];
            3'b001: y = a - b; cf = y[WIDTH - 1]; of = a[WIDTH - 1] ^ b[WIDTH - 1] ^ y[WIDTH - 1];
            3'b010: y = a & b; cf = 0;
            3'b011: y = a | b; cf = 0;
            3'b100: y = a ^ b; cf = 0;
            default: y = 0;
        endcase
        zf = (y == 0);
    end
endmodule

module arriaii_first_stage_add_sub(
                                 dataa,
                                 datab,
                                 sign,
                                 operation,
                                 dataout
                                );


input [71  : 0 ] dataa;
input [71 : 0 ] datab;
input sign;
input [3:0] operation;


output [71: 0] dataout;
parameter dataa_width = 36;
parameter datab_width = 36;
parameter fsa_mode = "add";

reg [71: 0] dataout_tmp;
reg [71: 0] abs_b;
reg [71: 0] abs_a;
reg sign_a;
reg sign_b;

always @*
begin
    if (operation == 4'b0000)
    begin
        dataout_tmp = dataa + datab;
    end
    else if (operation == 4'b0001)
    begin
        dataout_tmp = dataa - datab;
    end
    else if (operation == 4'b0010)
    begin
        dataout_tmp = dataa + datab[71:48];
    end
    else if (operation == 4'b0011)
    begin
        dataout_tmp = dataa + datab[47:24];
    end
    else if (operation == 4'b0100)
    begin
        dataout_tmp = dataa + datab[23:0];
    end
    else if (operation == 4'b0101)
    begin
        dataout_tmp = dataa - datab[71:48];
    end
    else if (operation == 4'b0110)
    begin
        dataout_tmp = dataa - datab[47:24];
    end
    else if (operation == 4'b0111)
    begin
        dataout_tmp = dataa - datab[23:0];
    end
    else if (operation == 4'b1000)
    begin
        dataout_tmp = dataa + datab[71:48] + datab[23:0];
    end
    else if (operation == 4'b1001)
    begin
        dataout_tmp = dataa + datab[47:24] + datab[23:0];
    end
    else if (operation == 4'b1010)
    begin
        dataout_tmp = dataa + datab[71:48] - datab[23:0];
    end
    else if (operation == 4'b1011)
    begin
        dataout_tmp = dataa + datab[47:24] - datab[23:0];
    end
    else if (operation == 4'b1100)
    begin
        dataout_tmp = dataa + datab[71:48] + datab[47:24];
    end
    else if (operation == 4'b1101)
    begin
        dataout_tmp = dataa + datab[47:24] + datab[71:48];
    end
    else if (operation == 4'b1110)
    begin
        dataout_tmp = dataa + datab[71:48] - datab[47:24];
    end
    else if (operation == 4'b1111)
    begin
        dataout_tmp = dataa + datab[47:24] - datab[71:48];
    end
    else
    begin
        dataout_tmp = dataa + datab;
    end
end

assign dataout = dataout_tmp;

endmodule

