module pddm (
	input sdi, 
	input signed_data, 
	output [31:0] dout, 
	input ock, uck, 
	input rstn, clk
);
reg [31:0] sigma;
	reg [31:0] undersampled_sigma;
	reg [31:0] delta;
	wire [31:0] deriv;

	assign deriv = sigma - undersampled_sigma;

	always @(posedge clk or negedge rstn) begin
		if (!rstn) begin
			sigma <= 0;
			undersampled_sigma <= 0;
		end else begin
			if (ock) begin
				if (sdi) begin
					sigma <= sigma + delta;
				end else begin
					sigma <= sigma - delta;
				end
			end
			if (uck) begin
				undersampled_sigma <= sigma;
			end
		end
	end

	assign dout = signed_data ? deriv : {deriv[31], deriv[31:1]};

endmodule

module RegFile(
    output reg signed  [31:0] ReadData1, ReadData2,
    input [4:0] ReadReg1, ReadReg2, WriteReg,
    input signed [31:0] WriteData,
    input RegWrite, Clk
    );
reg [31:0] RegFile [31:0];
    always @(negedge Clk)
    begin
        if(ReadReg1 != 0)
            ReadData1 <= RegFile[ReadReg1];
        else
            ReadData1 <= 0;
        if(ReadReg2 != 0)
            ReadData2 <= RegFile[ReadReg2];
        else
            ReadData2 <= 0;
    end
    always @(posedge Clk)
    begin
        if(RegWrite)
            RegFile[WriteReg] <= WriteData;
    end
endmodule

module ff_d_nand(
    output reg Q,
    input D, CLK, CLR_BAR   
);
parameter Vcc = 1.2;
    parameter C_L = 1.0;
    parameter t_hmin = 0.0;
    parameter t_hmax = 0.0;
    integer counter = 0;
    always @(posedge CLK) begin
        if (CLR_BAR) begin
            Q <= 1'b0;
        end else begin
            Q <= D;
        end
    end
    always @(posedge CLK) begin
        if (Q) begin
            counter <= counter + 1;
        end else begin
            counter <= counter - 1;
        end
    end
    always @(posedge CLK) begin
        if (Q) begin
            $display("PWR_DISS: %d", counter * C_L * Vcc^2);
        end
    end
endmodule

