module timer_stream_adapter_synchTime_2_fifo
#(parameter
    DATA_BITS  = 8,
    DEPTH_BITS = 4
)(
    input  wire                 clk,
    input  wire                 aclr,
    output wire                 empty_n,
    output wire                 full_n,
    input  wire                 read,
    input  wire                 write,
    output wire [DATA_BITS-1:0] dout,
    input  wire [DATA_BITS-1:0] din
);
localparam DEPTH = 1 << DEPTH_BITS;

reg empty, full;
reg [DEPTH_BITS-1:0] index;
reg [DATA_BITS-1:0] mem [DEPTH-1:0];

assign empty_n = ~empty;
assign full_n  = ~full;
assign dout    = mem[index];

always @(posedge clk or posedge aclr) begin
    if (aclr)
        empty <= 1'b1;
    else if (empty && write && !full)
        empty <= 1'b0;
    else if (!empty && !write && full)
        empty <= 1'b1;
end

always @(posedge clk or posedge aclr) begin
    if (aclr)
        full <= 1'b0;
    else if (full && read && !empty)
        full <= 1'b0;
    else if (!full && !read && empty)
        full <= 1'b1;
end

always @(posedge clk or posedge aclr) begin
    if (aclr)
        index <= {DEPTH_BITS{1'b1}};
    else if (empty && write)
        index <= index + 1;
    else if (full && read)
        index <= index - 1;
end

endmodule

module debounce(
input clk,
input btn_input,
output reg btn_output
); 

reg [31:0] timer;
reg pre;
  always @(posedge clk) begin
    if(timer == 1000000) begin
      if(btn_input == pre) begin
        btn_output <= btn_input;
      end
      timer <= 0;
      pre <= btn_input;
    end
    else begin
      timer <= timer + 1;
    end
  end
endmodule

