module gray_Nbits (clk, reset, enable, gray_out);

input wire clk, reset, enable;
output wire [N-1:0]gray_out;
parameter N = 4;
parameter SIZE = N+1;
parameter Zeros = {SIZE{1'b0}};

reg [SIZE-1:0]state;
reg [SIZE-1:0]toggle;

assign gray_out = state[SIZE-2:0];

always @(posedge clk or posedge reset)
begin
	if (reset)
		state <= Zeros;
	else if (enable)
		state <= state ^ toggle;
end

always @(state)
begin
	toggle[0] <= 1;
	toggle[1] <= state[0];
	toggle[2] <= state[1] ^ state[0];
	toggle[3] <= state[2] ^ state[1] ^ state[0];
	toggle[4] <= state[3] ^ state[2] ^ state[1] ^ state[0];
	toggle[5] <= state[4] ^ state[3] ^ state[2] ^ state[1] ^ state[0];
	toggle[6] <= state[5] ^ state[4] ^ state[3] ^ state[2] ^ state[1] ^ state[0];
	toggle[7] <= state[6] ^ state[5] ^ state[4] ^ state[3] ^ state[2] ^ state[1] ^ state[0];
	toggle[8] <= state[7] ^ state[6] ^ state[5] ^ state[4] ^ state[3] ^ state[2] ^ state[1] ^ state[0];
	toggle[9] <= state[8] ^ state[7] ^ state[6] ^ state[5] ^ state[4] ^ state[3] ^ state[2] ^ state[1] ^ state[0];
	toggle[10] <= state[9] ^ state[8] ^ state[7] ^ state[6] ^ state[5] ^ state[4] ^ state[3] ^ state[2] ^ state[1] ^ state[0];
	toggle[11] <= state[10] ^ state[9] ^ state[8] ^ state[7] ^ state[6] ^ state[5] ^ state[4] ^ state[3] ^ state[2] ^ state[1] ^ state[0];
	toggle[12] <= state[11] ^ state[10] ^ state[9] ^ state[8] ^ state[7] ^ state[6] ^ state[5] ^ state[4] ^ state[3] ^ state[2] ^ state[1] ^ state[0];
	toggle[13] <= state[12] ^ state[11] ^ state[10] ^ state[9] ^ state[8] ^ state[7] ^ state[6] ^ state[5] ^ state[4] ^ state[3] ^ state[2] ^ state[1] ^ state[0];
	toggle[14] <= state[13] ^ state[12] ^ state[11] ^ state[10] ^ state[9] ^ state[8] ^ state[7] ^ state[6] ^ state[5] ^ state[4] ^ state[3] ^ state[2] ^ state[1] ^ state[0];
	toggle[15] <= state[14] ^ state[13] ^ state[12] ^ state[11] ^ state[10] ^ state[9] ^ state[8] ^ state[7] ^ state[6] ^ state[5] ^ state[4] ^ state[3] ^ state[2] ^ state[1] ^ state[0];
end

endmodule

