 input clock, resetn;
 input [DATA_WIDTH-1:0] i_datain;
 input i_datain_valid;
 output reg o_datain_stall;
 output reg [DATA_WIDTH-1:0] o_dataout;
 input i_dataout_stall;
 output reg o_dataout_valid;
parameter DATA_WIDTH = 1;
 parameter INSERT_REGISTER = 0;

 always @ (posedge clock or negedge resetn)
 begin
  if (!resetn)
  begin
   o_datain_stall <= 1'b0;
   o_dataout <= {DATA_WIDTH{1'b0}};
   o_dataout_valid <= 1'b0;
  end
  else
  begin
   if (o_datain_stall)
    begin
     o_dataout_valid <= 1'b0;
     o_dataout <= {DATA_WIDTH{1'b0}};
    end
   else
    begin
     o_dataout_valid <= i_dataout_stall ? 1'b0 : o_datain_valid;
     o_dataout <= i_datain;
    end
   o_datain_stall <= i_datain_valid & i_dataout_stall;
  end
 end

endmodule

